<?php
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_obligation'])){ $st=$pdo->prepare("INSERT INTO obligations(contract_id,title,vendor_name,due_date,status,notes) VALUES(?,?,?,?,?,?)"); $st->execute([$_POST['contract_id']?:null,trim($_POST['title']),trim($_POST['vendor_name']),$_POST['due_date']?:null,$_POST['status'],trim($_POST['notes'])]); header('Location:index.php?page=obligations'); exit; }
$contractsList=$pdo->query("SELECT id,contract_no,title FROM contracts ORDER BY id DESC")->fetchAll();
$rows=$pdo->query("SELECT o.*,c.contract_no FROM obligations o LEFT JOIN contracts c ON c.id=o.contract_id ORDER BY COALESCE(o.due_date,'2999-12-31'),o.id DESC")->fetchAll();
$open=(int)$pdo->query("SELECT COUNT(*) FROM obligations WHERE status IN ('Open','Due Soon')")->fetchColumn();$over=(int)$pdo->query("SELECT COUNT(*) FROM obligations WHERE status='Overdue' OR (due_date<CURDATE() AND status<>'Completed')")->fetchColumn();$done=(int)$pdo->query("SELECT COUNT(*) FROM obligations WHERE status='Completed'")->fetchColumn();
?><div class="page-head"><div><h1>Obligations</h1><p>Monitor seluruh kewajiban dan deliverables kontrak.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#obligationModal"><i class="bi bi-plus-lg me-1"></i> Add Obligation</button></div>
<div class="mini-stats mb-4"><div><span>Open</span><strong><?=$open?></strong></div><div><span>Overdue</span><strong class="danger-text"><?=$over?></strong></div><div><span>Completed</span><strong class="success-text"><?=$done?></strong></div></div>
<div class="card p-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Obligation</th><th>Contract</th><th>Due Date</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php if($rows):foreach($rows as $r):$status=$r['status'];if($r['due_date']&&$r['due_date']<date('Y-m-d')&&$status!=='Completed')$status='Overdue';?><tr><td><strong><?=de($r['title'])?></strong><small class="d-block text-muted"><?=de($r['vendor_name']?:'-')?></small></td><td><?=de($r['contract_no']?:'-')?></td><td><?=de($r['due_date']?:'-')?></td><td><span class="status-pill <?=strtolower(str_replace(' ','-',$status))?>"><?=de($status)?></span></td><td><?=de($r['notes']?:'-')?></td></tr><?php endforeach;else:?><tr><td colspan="5" class="text-center text-muted py-5">Belum ada obligation.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal fade" id="obligationModal"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h5 class="fw-bold">Add Obligation</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Contract</label><select class="form-select mb-3" name="contract_id"><option value="">Pilih contract</option><?php foreach($contractsList as $c):?><option value="<?=$c['id']?>"><?=de($c['contract_no'].' — '.$c['title'])?></option><?php endforeach;?></select><label class="form-label">Obligation</label><input class="form-control mb-3" name="title" required><div class="row g-3"><div class="col-6"><label class="form-label">Vendor</label><input class="form-control" name="vendor_name"></div><div class="col-6"><label class="form-label">Due Date</label><input type="date" class="form-control" name="due_date"></div></div><label class="form-label mt-3">Status</label><select class="form-select mb-3" name="status"><option>Open</option><option>Due Soon</option><option>Completed</option><option>Overdue</option></select><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3"></textarea></div><div class="modal-footer"><button class="btn btn-primary" name="save_obligation">Save Obligation</button></div></form></div></div>
